input.command:
cd "C:/Users/edmem/OneDrive/Desktop/Minecraft Channel/studio/catalog" && python -c "
import json
t=json.load(open('taxonomy.json'));o=json.load(open('tags/zz_review_review_sfx_1.json'));a=json.load(open('tag_batches/review_sfx_1.json'))['assets']
assert [x['id'] for x in o]==[x['id'] for x in a]
fm={'Sound Effects/Minecraft':'sfx_minecraft','Sound Effects/Hits, Punches & Booms':'sfx_ui','Sound Effects/Risers & Suspense':'sfx_ui','Sound Effects/UI, Clicks & Notifications':'sfx_ui'}
bad=0
for x in o:
  e=[]
  e+=[m for m in x['moments'] if m not in t['moments']]+[r for r in x['roles'] if r not in t['roles']]
  if x['placement'] not in t['placement'] or x['key_mode'] not in t['key_modes'] or x['content_rating'] not in t['content_rating'] or x['copyright_risk'] not in t['copyright_risk'] or x['folder'] not in t['folders'] or x['category'] not in t['categories']: e.append('val')
  f=x['folder']; ec=fm.get(f, 'music' if f.startswith('Music') else 'sfx_meme')
  if x['category']!=ec: e.append('cat')
  if not(1<=len(x['moments'])<=5 and 1<=len(x['roles'])<=3 and 1<=x['energy']<=5): e.append('n')
  if e: bad+=1;print(x['id'],e)
print('bad',bad)
for x in o:
  if x['folder']!=a[o.index(x)]['path'].rsplit('/',1)[0] or x['clean_name']: print(x['id'][:40],'|',x['folder'][14:],x['roles'],x['clean_name'])
" | head -120

